const drawRuler = (firstPage, height, font) =>{

  

  /*  
  
   
  
   */
     
  Array.from(Array(200).keys()).map(g=>{
      
    
   
  
    firstPage?.drawText((g+1)*5%10? (g+1)*5 -5 + "" :".", {
      x: (g)*5,
      y: height - 790,
      size: 4,
      font: font,      
      color:  rgb(0, 0.1, 0.1)
    });
  
  })
  
  
  Array.from(Array(400).keys()).map((g)=>{
    
   
  
  
     firstPage?.drawText(( g%2!==0 ? (height - (g+1)*2.5 + 4).toFixed(1) : "") +  "- - - - - - -- - - - - - - - - - - - -- - - - - - - - - - - - -- - - - - - - - - - - - -- - - - - - - - - - - - -- - - - - - ", {
      x: 190,
      y: (g)*2.5,
      size: 4,
      font: font,      
      color:  g%2!==0 ?   rgb(0, 0.1, 0.1) :rgb(0.4, 0.81, 0.21) 
    });
  
  
  
  })
  
  
  
  }