import React, { useEffect, useState } from "react";



import {  gen16CodeId, parseDate, updStore, getStore, extractObjFlds, isSuperUser, downloadCSVFromJson, parseDateMMDDYYYY, AccountYears, qryStore, fetchEncryptStream, callDispatchEvent } from "../../../stores/Utils";



import "./styles.css"
import { AccountLabelDetail_Cmpt, SvgIcon_Cmpt } from "../../../components";
import { sortComprobantesByType } from "../services/server_fetching";
import { Comprobante2Pdf } from "../services/export_service";
import { CloseModal, OpenModal } from "../../../components/DialogHRM";
import {CodeVerifyView_Cmpt, UpdComprobante_Cmpt } from "..";
import { getall_employee } from "../../Employees/services/server_fetching";
import { getall_provider } from "../../ProvidersCustomers/services/server_fetching";
import { getYearAccBussines } from "../../FloatingSideMenu/component/SettingModal";


const AccountLabelDetail = AccountLabelDetail_Cmpt();
const UpdComprobante = UpdComprobante_Cmpt();


const CodeVerifyView = CodeVerifyView_Cmpt();

const Svg = SvgIcon_Cmpt();



const ViewComprobante  = ({ data, item, confirmYearClose }) => {
	const [initialize, setInitialize] = useState(false);
	const [, set_obs] = useState(0);


	
	useEffect(() => {
		if (!initialize) {
			setInitialize(true);

			if(item?.employeeId){
				if(!getStore("employees_ids")?.[item?.employeeId]){
					getall_employee(updObs);
				}
				
			}
			if(!getStore("providers_ids")){
				getall_provider(updObs);
			}
			set_obs(gen16CodeId())
		}
	});

	
	const send2pdf = () =>{
		Comprobante2Pdf(item)
	}

	const confirmYear2Close = () =>{
		let ClosYearId = gen16CodeId();
		setTimeout(() => {
			prepareAperComp(ClosYearId);
		}, 1750);

		confirmYearClose(ClosYearId)
	}

	const handleClose =   (v) => {

		v? CloseModal({id:v}) : data?.modalID && CloseModal({id:data?.modalID});
	}

	
	const requestCode =  async () => {
		
		let bdyq2 = {...getStore(qryStore())?.ask_notf_code};
		let tk = gen16CodeId()
		bdyq2.params = {
			businessId:  getStore("profileUser")?.businessId,
			phoneNumber: getStore("profileUser")?.phoneNumber,
			log: tk
		};
	   
		
		const res = fetchEncryptStream(bdyq2);
		const td = await res;
		
		if (td && !td.error) {
		
			let modaldata = {};
			modaldata["zIndex"] = 480;
			modaldata["height"] = "40vh";
			modaldata["content"] = <CodeVerifyView info={td} tmk={tk} confirm={confirmYear2Close}/>
			OpenModal(modaldata);
		}
	}


	const prepareAperComp =  (ClosYearId) => {

		
		let YY = getStore("date_current_year");
		// const date = new Date(`01/01/${ YY *1 +1} 00:00:59`);
		let commonFl = {
			businessId:  getStore("profileUser")?.businessId,
            date: item.date,
            comprobanteId: item.comprobanteId,
            description: item.description,
			year: YY *1 +1,
			businessYearId: getStore("YearAccBussines")?.[YY]?.businessYearId
        }


		

		
		let arrayAper = [];

		item.operations.map(reg=>{
			let ittm = {}
			if(reg?.debit){
				ittm.amount = reg?.debit;
				ittm.type = "debit";
			}else if(reg?.credit){
				ittm.amount = reg?.credit;
				ittm.type = "credit";
			}
			ittm.account = reg?.account?.accountId;
			if(reg?.sub_account?.sub_accountId){
				ittm.subAccount = reg?.sub_account?.sub_accountId;
				if(getStore("providers_subacc")?.[ittm.subAccount]?.providerId){
					ittm.providerId = getStore("providers_subacc")?.[ittm.subAccount]?.providerId;
				}
			}
			ittm.document = reg?.document;
			ittm.operationId = gen16CodeId();

			
			arrayAper.push(ittm);
		})
		

		let bdyq2 = {...getStore(qryStore())?.close_hrm_years};
		
		bdyq2.params = commonFl;
		bdyq2.form = arrayAper;

		
		fetchCloseYear(bdyq2, ClosYearId);
		//CloseMYear(ClosYearId);

	}

	const fetchCloseYear = async (bdyq2, ClosYearId) => {
		const res = fetchEncryptStream(bdyq2);
		const td = await res;
		if (td && !td.error) {
			CloseMYear(ClosYearId);
			getYearAccBussines();
		}
	}

	const CloseMYear = ( ClosYearId) => {
		setTimeout(() => {
			handleClose(ClosYearId);
			handleClose();
			//callDispatchEvent("dimention_hash");
		}, 2500);
	}


	const exportFiltered =  () => {
		let nArr = [];
		item.operations && item.operations?.map((element,ind43) => {
			let hh = {...element};
			hh.description = item.description;
			hh.comprobanteId = item.comprobanteId;
			hh.date = parseDateMMDDYYYY(item.date);
			hh.description = item.description;
			let account = element.account.code +" - "+  element.account.name
			hh.account = account;
			if(hh.sub_account){
				let subaccount = element.sub_account.subAccount +" - "+  element.sub_account.subAccountName
				hh.sub_account = subaccount;
			}
			nArr.push(hh)
		});
		
		downloadCSVFromJson('export_compobante_'+ item.comprobanteId +"_"+gen16CodeId()+'.csv',nArr);
	}



	const updObs = () =>{
		set_obs(gen16CodeId())
	}

	let employeeId = getStore("employees_ids")?.[item?.employeeId]?.name;


	let isNotValid = (item.balance?.toFixed(2))*1 !== 0;

	return (
		<div style={{
			maxHeight: "96vh",
			minHeight: "90vh",
			width: "960px",
			overflow: "auto",
			background: "var(--hrm_palette-general-background-b)",
			borderRadius: 13,
			padding: "10px 19px"
		}}>
			<div className="_dsplFlx ">
				<div className="flexSpace"/>
				
			</div>
			<div className="_dsplFlx ">
				<div className="_dsplFlx" style={{marginTop: 20}} >
					<div className="desc_lbl" >
						{"Comprobante:"} 
					</div>
					<div className="name comprobante_id"  style={isNotValid ?{color:"var(--hrm_palette-selected-nav-text)"}:{}}>
						{item?.comprobanteId}
					</div>
				</div>
				{isNotValid ?
				<div className="msg_alert">
					<div className="msg_alert_title">
						El comprobante no esta cuadrado {item?.balance?.toFixed(2)}
					</div>
				</div>
				:<div className="msg_alert hrm_themecolor green darkwgreen" onClick={requestCode}>
					<div className="msg_alert_title">
						El comprobante esta listo y verificado para la apertura del 2024
					</div>
				</div>
				}
				<div className="flexSpace"/>
				
				<div className="icon" onClick={exportFiltered} style={{marginRight:17}}>
					<Svg name={"google-spreadsheet"} color={"#282828"}/>
				</div>
				<div className="icon" onClick={send2pdf}>
					<Svg name={"printer"} color={"#282828"}/>
				</div>
			</div>

			
			<div className="_dsplFlx cmp_dtls">
				
				<div className="flexSpace"/>
				<div className="_dsplFlx"  >
					<div className="desc_lbl" >
						{} 
					</div>
					<div className="name">
						{ parseDate(item?. date)}
					</div>
				</div>
			
				
			</div>




			
			<div className="_dsplFlx hdr_bar purple">
				<div className="tr_bar_15">
					Cuenta
				</div>
				<div className="tr_bar_15">
					Sub Cuenta
				</div>
				<div className="tr_bar_40">
					Documento
				</div>
				<div className="tr_bar_15">
					Debito
				</div>
				<div className="tr_bar_15">
					Credito
				</div>
			</div>

			{sortComprobantesByType(item?.operations)?.map((element, in2D) => 
				<ItemRecord element={element} in2D={in2D} key={in2D}/>
			)}

			<div className="cmp_desc">
				<div className="desc_lbl" >
					{"Detalles:"} 
				</div>
				<div className="description">
					{ item?. description} {employeeId}
				</div>
				
				
				
			</div>
			<div className="_dsplFlx cmp_dtls">
				<div className="flexSpace"/>
				<span className="entryType">
					{item.entryName || "Comprobante Manual"}
				</span>
			</div>
			
		</div>
	);
};

export default ViewComprobante;





const ItemRecord = ({element, in2D }) =>{

	const OpenDeleteRecord =  () => {
		if(AccountYears()[getStore("date_current_year")]?.isClosed){

		}
		else{
			if(isSuperUser()){
				let lastTimeCallModal = getStore("lastTimeCallModal") || 0;
				if(Date.now() > lastTimeCallModal){
					let flds = ["document","amount","type","description", "account", "subAccount", "comprobanteId"]

					let frm2Upd = extractObjFlds({...getStore("comprobante_list")[element.operationId]},flds)
					
					updStore("upd_comprobantebyId", frm2Upd);
					updStore("upd_comprobantebyId_bck", JSON.parse(JSON.stringify(frm2Upd)));
					updStore("lastTimeCallModal", Date.now()+320);
					let modaldata = {};
					modaldata["zIndex"] = 450;
					modaldata["height"] = "40vh";
					// data['observeResize']=true;
					modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
					modaldata["content"] = <UpdComprobante confirm={ ()=>{}} item={element} />
					OpenModal(modaldata);
				}
			}
		}
	}


	return (
			<div className="_dsplFlx hdr_bar" key={in2D}>
				<div className="tr_bar_15">
					<AccountLabelDetail 
						data={element.account}
						labelField={"code"}
						infoField={"name"}
					/>
				</div>
				<div className="tr_bar_15">
					<AccountLabelDetail 
						data={element.sub_account}
						labelField={"subAccount"}
						infoField={"subAccountName"}
					/>
				</div>
				<div className="tr_bar_40" onClick={OpenDeleteRecord}>
					{element.document}
				</div>
				<div className="tr_bar_15">
					{(element.debit*1)?.toFixed(2)}
				</div>
				<div className="tr_bar_15">
					{(element.credit*1)?.toFixed(2)}
				</div>
			</div>
	)
}








