

import React, {useState} from "react";

import "./styles.css"
import { CloseModal, OpenModal } from "../../../components/DialogHRM";
import { SvgIcon_Cmpt, CheckBoxSlide_Cmpt, DropDwnPicker_Cmpt } from "../../../components";
import { getStore, updStore, gen16CodeId, isSuperUser, tokenNameCookie, callDispatchEvent, qryStore, fetchEncryptStream } from "../../../stores/Utils";
import { CodeVerifyView_Cmpt } from "../../Comprobantes";

const Svg = SvgIcon_Cmpt();

const CheckBoxSlide = CheckBoxSlide_Cmpt();

const DropDwnPicker = DropDwnPicker_Cmpt();

const CodeVerifyView = CodeVerifyView_Cmpt();


const SettingModal  = ({ data, confirm, handleClick, close }) => {
	const [, set_obs] = useState(0);

	const { modalID } = data;

	const handleClose =  (v) => {
		CloseModal({id:modalID})
    }
    
    const handleConfirm =  () => {
		
        confirm();
		handleClose();
	}

	const handlePrintStyle =  (v) => {

		if(v && !getStore("modernFontReport")){
			updStore("modernFontReport",v);
			set_obs(gen16CodeId())
		}
		else if(!v && getStore("modernFontReport")){
			updStore("modernFontReport",v);
			set_obs(gen16CodeId())
		}
	}


	const handleYear =  (y) => {
		updStore("date_current_year",y);
		let initDate = (new Date("01/01/"+y)).getTime(); 
		let lastDate = (new Date("01/01/"+(y+1))).getTime() - 10;
		updStore("date_range_comps", {initDate,lastDate} )
		updStore("date_range_submayor", {initDate,lastDate} )
		/*
		let tdV = {
			2022:{isCurrentYear: false, isClosed: false, businessYearId: 'rbw3nJFbpmKDXg7c'},
			2023:{isCurrentYear: false, isClosed: true, businessYearId: 'EkhoSZWy7lHt2Mqr'},
			2024:{isCurrentYear: false, isClosed: false, businessYearId: '0BzZVf7DO1N20o8F'}
		}

		updStore("YearAccBussines",tdV);
		*/
		//console.log(getStore("YearAccBussines")?.[y])
		if(!getStore("YearAccBussines")?.[y]?.businessYearId){
			addYearAccBussines(y);
		}
		set_obs(gen16CodeId())
		callDispatchEvent("dimention_hash");
	}

	


	const addYearAccBussines = async ( year) =>{
		let Qry_V = getStore(qryStore())?.add_hrm_years;
		if(year && Qry_V){
		  Qry_V.params = {
			businessId:  getStore("profileUser")?.businessId,
			year
		  }
		  const resV = fetchEncryptStream(Qry_V);
		  const tdV = await resV;
		  if (tdV) {
			getYearAccBussines();
		  }
		}
	  }


	
	const handleTheme =  () => {
		let darkTheme = getStore("darkTheme")?true:false;
		let nTheme = !darkTheme;

		const el = document.querySelector('[theme*="92357239"]');
		if(el){
			el.className = nTheme? "light_theme palette_body App ":"dark_theme  palette_body App ";
		};
		let html = document.children[0];
		html.style.backgroundColor =  nTheme? "#f1f1f1": "#212121";
		updStore("darkTheme",nTheme);
		set_obs(gen16CodeId())

		
		
	}
	
	const handleLogs =  (v) => {
		updStore("showLog",v);
		set_obs(gen16CodeId())
	}
	
	const logout =  (v) => {
		document.cookie = `${tokenNameCookie()}=""`;
		document.cookie = `hrm_access_tkn = ""`;
		document.cookie = `F2Atkn = ""`;
		updStore("profileUser",null)
		updStore("isAdmin",null);
		handleClose();
        callDispatchEvent("dimention_hash");
    }
	




    return (
		<div style={{
			maxHeight: "80vh",
			minHeight:  "40vh",
			width:"560px",
			overflow: "auto",
			background: "var(--hrm_palette-general-background-b)",
			borderRadius: 13,
			padding: "10px 19px",
			
		}}>
			<div className="_dsplFlx ">
				<p className="form_title">
					Settings
				</p>
				<div className="flexSpace"/>
				{isSuperUser()?
				<div className="_dsplFlx " style={{marginTop: 4}}>
					<CheckBoxSlide
						initvalue={getStore("showLog")}
						keyCode={77}
						updChange={(e)=>handleLogs(e)}
					/>
					<span className={`checklabel`}>
						{"Show Logs"}
					</span>
				</div>
				:null}
			</div>
			<div className="theme_setting_box "  style={{margin: "13px 0"}}s>

				<div className="_dsplFlx spaceAround ">
					<div>
						<div className="_dsplFlx spaceAround"  style={{padding: 3}}>
							<DropDwnPicker 
								init={getStore("date_current_year")}
								lbl_empty={"Location"} 
								list={[
									{id:2022,label:2022},
									{id:2023,label:2023},
									{id:2024,label:2024}
								]} 
								onSelect={(e)=>handleYear(e.id)}
								background={"#f9f9f9"}
								color={"var(--hrm_palette-blue-purple)"}
								direction={"left"}
								width={"220px"}
							/>
							
							
						</div>
					</div>
					<div className={`theme_style`} onClick={handleTheme}>
					
						<Svg name={"theme"}	color={"var(--hrm_palette-general-background-b)"}/>
						<div className="title gSansFont">
							{getStore("darkTheme")?"Dark":"Light"} 
						</div>
					</div>
				</div>
			</div>

			<div className="print_setting_box ">

							
				<div className="header ">
					<span>
						Estilo de Impresion
					</span>
				</div>
				<div className="_dsplFlx spaceAround ">

					<div className={`print_style modern ${getStore("modernFontReport")?"active":""}`}  onClick={()=>handlePrintStyle(true)}>
						<Svg 
							name={"check_circle"}	/>
						<div className="title">
							Modern
						</div>
						<div className="body">
							<h4>
								Fuente Normal
							</h4>
							<h5>
								Fuente Negrita
							</h5>
						</div>
					</div>
					<div className={`print_style classic ${getStore("modernFontReport")?"":"active"}`} onClick={()=>handlePrintStyle(false)}>
					
							<Svg 
							name={"check_circle"}	/>
						
						<div className="title">
							Classic
						</div>
						<div className="body">
							<h4>
								Fuente Normal
							</h4>
							<h5>
								Fuente Negrita
							</h5>
						</div>
					</div>
				</div>
			</div>


			<div className="_dsplFlx " style={{padding:"15px 10px"}}>
				<div className="flexSpace"/>
				<p className="group_title addBtn" onClick={logout}>
					Logout
				</p>
				<p className="group_title addBtn" onClick={handleClose}>
					Cerrar
				</p>
				<p className="group_title addBtn purple" onClick={handleConfirm}>
					Guardar
				</p>
			</div>

		</div>
    )   
}

export default SettingModal;




